import json,hashlib,shlex,re
from pathlib import Path
S=Path('/home/user/src/work-leaf/bench-results/efficiency-mechanism-isolation-20260906T214448Z')
path=S/'EVIDENCE-H-POSTGREEN-ACTIVITY.json';v=json.loads(path.read_bytes());old=json.loads((S/'EVIDENCE-H-VALIDATION-CADENCE.json').read_bytes())
sha=lambda b:hashlib.sha256(b).hexdigest()
for p,h in v['source_sha256'].items():assert sha(Path(p).read_bytes())==h,p
seen=set();window=set();whole=set();fix=set();failingfix=set();retained=0;patches=0;counts={};failures=0;compounds=[]
for a in v['authors']:
 data=Path(a['native_source']['path']).read_bytes(); rows={n:json.loads(s) for n,s in enumerate(data.splitlines(),1)}
 assert sha(data)==a['native_source']['sha256']
 prior=old['direct_initial_authors'][a['index']]
 assert (a['run_id'],a['feature'],a['thread_id'])==(prior['run_id'],prior['feature'],prior['thread_id'])
 for r in prior['initial_window_checks']:window.add((a['thread_id'],r['call_id']))
 for n,raw in rows.items():
  q=raw.get('payload',{})
  if raw['type']=='response_item' and q.get('type')=='function_call' and q.get('name')=='exec_command':
   cmd=json.loads(q['arguments'])['cmd']
   try:tokens=shlex.split(cmd)
   except ValueError:tokens=[]
   if len(tokens)>1 and tokens[:2]==['cargo','test']:whole.add((a['thread_id'],q['call_id']))
 byline={r['line']:r for r in a['validation_and_patch_actions']}
 for u in a['review_fix_inputs']:
  p=rows[u['line']]['payload'];body=''.join(c.get('text','') for c in p.get('content',[]) if c.get('type')=='input_text')
  assert p['role']=='user' and p.get('id')==u['item_id'] and sha(body.encode())==u['text_sha256']
  assert u['findings_section'] in body
  fix.add((a['thread_id'],u['turn_id']))
 episodes={}
 for e in a['failure_episodes']:
  for line in e['failed_call_lines']:
   assert line not in episodes;episodes[line]=e['id']
  for field in ['test_setup_patch_lines','production_patch_lines','fixture_or_removed_patch_lines']:
   assert all(byline[n]['type']=='apply_patch' and byline[n]['exit']==0 for n in e[field])
  for check in e['subsequent_check_evidence']:
   rawout=rows[check['output_line']]['payload']['output']
   for name in check['previously_failed_names_reported_ok']:assert re.search('^test '+re.escape(name)+r' \.\.\. ok$',rawout,re.M)
 for r in a['validation_and_patch_actions']:
  q=rows[r['line']]['payload'];o=rows[r['output_line']]['payload']
  assert q['call_id']==o['call_id']==r['call_id']
  assert q.get('id')==r['item_id'] and o.get('id')==r['output_item_id']
  assert sha(q.get('arguments',q.get('input')).encode())==r['input_sha256']
  assert sha(o['output'].encode())==r['output_sha256']
  assert r['turn_id']==r['output_turn_id'] and r['turn_id'] in a['expected_author_turns']
  if r['type']=='apply_patch':patches+=1;continue
  assert json.loads(q['arguments'])['cmd']==r['command']
  assert sha(r['command'].encode())==r['command_sha256']
  if '&&' in r['command']:compounds.append((a['index'],r['line'],r['exit']))
  if r['in_remainder_test_leading_population']:
   ident=(a['thread_id'],r['call_id']);assert ident not in seen;seen.add(ident);retained+=1
   counts[r['classification']]=counts.get(r['classification'],0)+1
   if r['exit']!=0:
    failures+=1;assert r['failure_episode_id']==episodes[r['line']]
    if r['failed_tests'] and r['stage']=='later-author-fix-turn':failingfix.add((a['thread_id'],r['turn_id']))
 assert a['counts']['remainder_test_leading_calls']==sum(r.get('in_remainder_test_leading_population',False) for r in a['validation_and_patch_actions'])
assert len(v['authors'])==18 and len(fix)==21 and len(failingfix)==20
assert len(window)==92 and len(whole)==420 and len(seen)==328 and window.isdisjoint(seen) and window|seen==whole
assert failures==48 and counts==v['counts']['remainder_dispositions']
assert len(compounds)==13 and sum(exit!=0 for _,_,exit in compounds)==2
assert len(set(a['thread_id'] for a in v['authors']))==18
for p,h in v['source_sha256'].items():assert sha(Path(p).read_bytes())==h,p
print(json.dumps({'status':'PASS','authors':18,'fix_turns':len(fix),'fix_turns_with_executed_failure':len(failingfix),'prior_window':len(window),'whole_test_leading':len(whole),'remainder':retained,'failed_test_leading_commands':failures,'retained_patch_attempts':patches,'compound_commands':len(compounds),'source_endpoints':len(v['source_sha256']),'json_sha256':sha(path.read_bytes()),'bytes':path.stat().st_size,'counts':counts}))
